package process

import (
 "encoding/json"
 "fmt"
 "io"
 "net/http"
 "net"
 "net/url"
 "os"
 "strconv"
 "time"
 C "github.com/metacubex/mihomo/constant"
)

// Jeemi supplies an authenticated, session-scoped Android connection owner
// resolver. No app inventory or traffic metadata is written to disk.
func init() {
 address, token := os.Getenv("JEEMI_ANDROID_OWNER"), os.Getenv("JEEMI_ANDROID_TOKEN")
 if host, _, err := net.SplitHostPort(address); err != nil || host != "127.0.0.1" || len(token) < 32 { return }
 PlatformPackageResolver = true
 client := &http.Client{Timeout: 800*time.Millisecond, Transport: &http.Transport{Proxy:nil, MaxIdleConnsPerHost:8}, CheckRedirect:func(*http.Request,[]*http.Request) error{return http.ErrUseLastResponse}}
 DefaultPackageNameResolver = func(metadata *C.Metadata) (string,error) {
  q := url.Values{"network":{metadata.NetWork.String()},"source":{metadata.SrcIP.String()},"destination":{metadata.DstIP.String()},"sourcePort":{strconv.Itoa(int(metadata.SrcPort))},"destinationPort":{strconv.Itoa(int(metadata.DstPort))}}
  if metadata.RawDstAddr != nil { if host,port,err := net.SplitHostPort(metadata.RawDstAddr.String()); err == nil { q.Set("destination",host);q.Set("destinationPort",port) } }
  request,err := http.NewRequest(http.MethodGet,"http://"+address+"/owner?"+q.Encode(),nil)
  if err != nil { return "",ErrNotFound }
  request.Header.Set("Authorization","Bearer "+token)
  response,err := client.Do(request)
  if err != nil { return "",ErrNotFound }
  defer response.Body.Close()
  if response.StatusCode != 200 { return "",ErrNotFound }
  var result struct { UID int64 `json:"uid"`; Package string `json:"package"` }
  if json.NewDecoder(io.LimitReader(response.Body,4096)).Decode(&result) != nil || result.UID < 0 { return "",ErrNotFound }
  metadata.Uid = uint32(result.UID)
  if result.Package == "" { return "",fmt.Errorf("package unavailable") }
  metadata.ProcessPath = ""
  return result.Package,nil
 }
}

