//go:build android

package dialer

import (
    "fmt"
    "io"
    "net"
    "os"
    "strings"
    "syscall"
    "time"
)

// The child owns the original socket. Send a duplicate over a private,
// session-scoped Unix socket so VpnService can protect the same kernel socket.
// Never proceed with an unprotected outbound connection after a bridge failure.
func init() {
    address, token := os.Getenv("JEEMI_ANDROID_PROTECT"), os.Getenv("JEEMI_ANDROID_PROTECT_TOKEN")
    if address == "" && token == "" { return }
    DefaultSocketHook = func(network, destination string, raw syscall.RawConn) error {
        if !strings.HasPrefix(address, "@jeemi-protect-") || len(token) != 64 { return fmt.Errorf("Android socket protection unavailable") }
        connection, err := net.DialTimeout("unix", address, time.Second)
        if err != nil { return fmt.Errorf("Android socket protection unavailable") }
        defer connection.Close()
        socket, ok := connection.(*net.UnixConn)
        if !ok { return fmt.Errorf("Android socket protection unavailable") }
        _ = socket.SetDeadline(time.Now().Add(2*time.Second))
        var sendError error
        err = raw.Control(func(fd uintptr) {
            n, _, e := socket.WriteMsgUnix([]byte(token), syscall.UnixRights(int(fd)), nil)
            if e != nil { sendError = e } else if n != len(token) { sendError = io.ErrShortWrite }
        })
        if err != nil || sendError != nil { return fmt.Errorf("Android socket protection failed") }
        var response [1]byte
        if _, err := io.ReadFull(socket, response[:]); err != nil || response[0] != 1 { return fmt.Errorf("Android socket protection rejected") }
        return nil
    }
}
